const state={data:emptyData(),mode:null,config:null,cloud:null,repo:null,authUnsubscribe:null,userEmail:'',ready:false,connected:false,saving:0,route:'hoy',navOpen:false,query:'',companyStatus:'',sector:'',priority:'',companySegment:'todas',companySort:'recientes',page:1,selectedCompanies:new Set(),dealQuery:'',dealCurrency:'todas',pipelineView:matchMedia('(max-width:650px)').matches?'list':'board',taskQuery:'',taskKind:'',taskFilter:'pendientes',calendarDate:today(),selectedDate:today(),calendarType:'',calendarView:'month',salesCurrency:'PEN',salesFilter:'todas',outreachQuery:'',outreachChannel:'',outreachCity:'',outreachDistrict:'',outreachStage:'',outreachPeriod:'',outreachStatus:'',queueError:'',reportCurrency:'PEN',reportPeriod:'todos',importing:false,campaignBusy:false};
