function toast(message,tone='success') { const item=document.createElement('div');item.className=`toast ${tone}`;item.setAttribute('role',tone==='error'?'alert':'status');item.innerHTML=`${icon(tone==='error'?'alert':'check')}<span>${e(message)}</span>`;$('#toast-region').append(item);setTimeout(()=>item.remove(),tone==='error'?9000:5500); }
function friendly(error) { const code=error?.code||'';if(/invalid-credential|invalid_credentials|wrong-password|user-not-found|invalid-email/.test(code)||/Invalid login credentials/.test(error?.message||''))return 'Revisa el correo y la contraseña de tu cuenta.';if(/too-many-requests/.test(code))return 'Hubo demasiados intentos. Espera unos minutos y vuelve a intentar.';if(/network-request-failed|unavailable/.test(code))return 'No se pudo conectar. Revisa internet y vuelve a intentarlo.';if(/permission-denied/.test(code))return 'La cuenta no tiene acceso a los datos. Autoriza tu UUID desde SQL Editor de Supabase.';return error?.message||'No se pudo completar la operación. Tus cambios no se han confirmado.'; }
function preserveFocus() {const active=document.activeElement;if(!$('#app').contains(active))return null;return {id:active.id,filter:active.dataset.filter,action:active.dataset.action,recordId:active.dataset.id,start:active.selectionStart,end:active.selectionEnd};}
function render() {
  const focus=preserveFocus();const goals=$('#goals-form');if(goals&&goals.dataset.dirty==='true')goalsDraft=Array.from(new FormData(goals).entries());
  if(!state.mode)$('#app').innerHTML=gate(state.config,gateError);
  else if(!state.ready)$('#app').innerHTML=`<main class="boot" id="main"><img src="/brand/nexo-logo.svg" alt="Nexo" width="180" height="63"><p>Conectando tu espacio personal…</p><p class="muted">Esperando la confirmación de tu base de datos.</p>${action('Revisar conexión','connection',{class:'text-button',icon:'settings'})}${action('Cerrar sesión','logout',{class:'text-button'})}</main>`;
  else if(!state.importing)$('#app').innerHTML=shell(state.data,state,viewFor(state.data,state));
  if(focus){let element=focus.id?document.getElementById(focus.id):focus.filter?$(`[data-filter="${focus.filter}"]`):null;if(!element&&focus.action)element=$(`#app [data-action="${focus.action}"]${focus.recordId?`[data-id="${CSS.escape(focus.recordId)}"]`:''}`);if(element){element.focus({preventScroll:true});if(focus.start!==null&&element.setSelectionRange)try{element.setSelectionRange(focus.start,focus.end)}catch{}}}
  if(goalsDraft&&$('#goals-form')){for(const [name,value] of goalsDraft){const control=$('#goals-form').elements.namedItem(name);if(control)control.value=value;}$('#goals-form').dataset.dirty='true';}
  const sync=$('.sync-state');if(sync){sync.innerHTML=`<i></i>${state.saving?'Guardando…':state.mode==='demo'?'Prueba local':state.connected?'Sincronizado':'Sin conexión'}`;sync.classList.toggle('saving',state.saving>0);}
}
function route(next){state.route=NAV.some(item=>item.key===next)?next:'hoy';state.navOpen=false;render();if(state.ready){$('#main')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});} }
function navigate(next){if(location.hash===`#${next}`)route(next);else location.hash=next;}
function onData(data,status){state.data=data;state.ready=status.ready;state.connected=status.connected;render();}
async function enterDemo(){sessionStorage.setItem('nexo-crm-demo-active','1');state.repo?.stop();state.mode='demo';state.cloud&&await state.cloud.logout();state.ready=false;state.repo=new DemoRepository(onData);await state.repo.start();state.route=location.hash.slice(1)||'hoy';route(state.route);}
async function initializeCloud(config){state.authUnsubscribe?.();state.repo?.stop();if(state.cloud){await state.cloud.close();state.cloud=null;}state.config=config;state.cloud=await createCloud(config);state.authUnsubscribe=state.cloud.watchAuth(async user=>{if(state.mode==='demo')return;if(!user){if(!state.mode&&!state.ready)return;state.repo?.stop();state.repo=null;state.mode=null;state.data=emptyData();state.ready=false;render();return;}try{syncError=false;state.mode='cloud';state.userEmail=user.email||'';state.ready=false;state.connected=false;render();state.repo?.stop();state.repo=state.cloud.repository(user,onData,error=>{if(syncError)return;syncError=true;state.repo?.stop();state.mode=null;state.ready=false;state.data=emptyData();gateError=friendly(error);render();});await state.repo.start();}catch(error){gateError=friendly(error);state.repo?.stop();state.mode=null;render();}});}
function companyDuplicateNotice(){
 const form=$('#company-form'),notice=$('#company-duplicates');if(!form||!notice)return;
 const values=Object.fromEntries(new FormData(form));const matches=companyDuplicates(values,state.data.companies,values.id,state.data.contacts);notice.hidden=!matches.length;
 notice.innerHTML=matches.length?`<strong>Estos datos ya aparecen en tu CRM</strong><p>Revisa las coincidencias antes de guardar. Tu borrador se conserva.</p><ul>${matches.map(({company,fields})=>`<li><div><strong>${e(company.name)}${company.archived?' (archivada)':''}</strong><span>${fields.map(field=>e(field.label)+': '+e(field.value)).join(' · ')}</span></div>${action('Ver empresa','open-company',{id:company.id,class:'text-button',icon:'diagonal'})}</li>`).join('')}</ul>`:'';
}
function focusDetailTab(){const tab=$('#record-dialog [role="tab"][aria-selected="true"]');if(!tab)return;tab.focus({preventScroll:true});const list=tab.parentElement;const left=tab.offsetLeft-list.offsetLeft;if(left<list.scrollLeft)list.scrollLeft=left;else if(left+tab.offsetWidth>list.scrollLeft+list.clientWidth)list.scrollLeft=left+tab.offsetWidth-list.clientWidth;}
function currentFormSignature(){const form=$('#dialog-content form');return form?JSON.stringify(Array.from(new FormData(form).entries())):'';}
function editingDirty(){return initialForm&&currentFormSignature()!==initialForm;}
function showDialog(html,context={},wide=false){const dialog=$('#record-dialog');if(!dialog.open){trigger=document.activeElement;triggerSelector=trigger?.dataset.action?`#app [data-action="${trigger.dataset.action}"]${trigger.dataset.id?`[data-id="${CSS.escape(trigger.dataset.id)}"]`:''}`:'';}modal=context;$('#dialog-content').innerHTML=html;dialog.classList.toggle('wide',wide);if(!dialog.open)dialog.showModal();dialog.scrollTop=0;initialForm=currentFormSignature();$('#dialog-title')?.focus({preventScroll:true});}
function closeDialog(){whatsappDialog.close();emailDialog.close();initialForm='';$('#record-dialog').close();modal=null;}
async function requestClose(){if(modal?.kind==='campaign'&&state.campaignBusy){toast('Espera a que termine la campaña actual.','error');return;}if(modal?.kind==='whatsapp'&&whatsappDialog.busy){toast('Espera a que se confirme el intento de WhatsApp.','error');return;}if(state.importing){toast('Espera a que termine el bloque de importación antes de cerrar.','error');return;}if(editingDirty()&&!await confirmDialog('¿Descartar los cambios sin guardar?','Puedes seguir editando o cerrar esta ventana.','Descartar cambios'))return;closeDialog();}
async function confirmDialog(title,description,confirm='Confirmar'){const dialog=$('#confirm-dialog');$('#confirm-content').innerHTML=`<h2 id="confirm-title">${e(title)}</h2><p>${e(description)}</p><div class="form-footer"><button class="button secondary" data-confirm="cancel" type="button">Seguir aquí</button><button class="button" data-confirm="yes" type="button">${e(confirm)}</button></div>`;dialog.showModal();return new Promise(resolve=>{const click=event=>{const button=event.target.closest('[data-confirm]');if(button){cleanup();dialog.close();resolve(button.dataset.confirm==='yes')}};const cancel=event=>{event.preventDefault();cleanup();dialog.close();resolve(false)};function cleanup(){dialog.removeEventListener('click',click);dialog.removeEventListener('cancel',cancel)}dialog.addEventListener('click',click);dialog.addEventListener('cancel',cancel);dialog.querySelector('[data-confirm="cancel"]').focus();});}
function openCompany(recordId,tab='resumen'){const row=get('companies',recordId);if(row)showDialog(forms.companyDetail(state.data,row,tab),{kind:'company',id:recordId,tab},true);}
function openDeal(recordId,tab='resumen'){const row=get('deals',recordId);if(row)showDialog(forms.dealDetail(state.data,row,tab),{kind:'deal',id:recordId,tab},true);}
function refreshDetail(){if(modal?.kind==='company')openCompany(modal.id,modal.tab);else if(modal?.kind==='deal')openDeal(modal.id,modal.tab);}
function formBack(){const back=modal?.back;if(back?.kind==='company')openCompany(back.id,back.tab);else if(back?.kind==='deal')openDeal(back.id,back.tab);else closeDialog();}
function showForm(html,context={}){const back=['company','deal'].includes(modal?.kind)?{...modal}:modal?.back;showDialog(html,{kind:'form',back,...context});}
async function write(operations,message='Cambios guardados.'){if(!state.repo)throw new Error('Inicia sesión o entra al espacio de prueba.');state.saving++;render();try{await state.repo.commit(operations);if(message)toast(message);}finally{state.saving--;render();}}
function systemActivity(companyId,dealId,body){return {id:id(),company_id:companyId,deal_id:dealId||'',kind:'sistema',outcome:'comentario',body,date:today(),time:localTime()};}
function mergeOperations(operations){const unique=new Map();for(const item of operations){const key=item.type+':'+item.record.id;const prior=unique.get(key);if(prior&&prior.expected!==item.expected)throw new ConflictError();unique.set(key,prior?{...item,record:{...prior.record,...item.record}}:item);}return [...unique.values()];}
function closureOperations(deal,original){
 const stage=dealStageKey(deal),company=get('companies',deal.company_id),changed=!original||dealStageKey(original)!==stage;
 const list=[];
 // Editing a historical sale or loss must not move the company's current cycle.
 if(company&&(changed||original.company_id!==deal.company_id)){
  if(stage==='ganada')list.push(saleCompanyOperation(company));
  else list.push(...stageOperations(state.data,company,stage,{allowContact:stage==='demo',reason:deal.lost_reason||''}));
 }
 list.push(op('deals',{...deal,pipeline_version:2},original?.version||0));
 const followId='followup-'+deal.id,previousFollow=get('tasks',followId);
 if(isOpen(deal)&&deal.next_step&&deal.next_action_date){const nextChanged=deal.next_step!==original?.next_step||deal.next_action_date!==original?.next_action_date;list.push(op('tasks',{...previousFollow,id:followId,title:deal.next_step.slice(0,220),company_id:deal.company_id,deal_id:deal.id,kind:'seguimiento',due_date:deal.next_action_date,due_time:previousFollow?.due_time||'',priority:previousFollow?.priority||'media',status:nextChanged?'pendiente':previousFollow?.status||'pendiente',duration:previousFollow?.duration||30,meeting_url:previousFollow?.meeting_url||'',notes:previousFollow?.notes||'',auto_followup:true},previousFollow?.version||0));}
 else if(!isOpen(deal)&&previousFollow&&isPending(previousFollow))list.push(op('tasks',{...previousFollow,status:'cancelada'}));
 if(changed)list.push(op('activities',systemActivity(deal.company_id,deal.id,`Oportunidad ${STAGES[stage].toLowerCase()}: ${deal.title}`),0));
 if(deal.stage==='ganada'&&original?.stage!=='ganada'&&!state.data.milestones.some(row=>row.deal_id===deal.id))for(const title of ['Acordar el alcance de la primera etapa','Presentar una primera versión','Validar y entregar'])list.push(op('milestones',{id:id(),deal_id:deal.id,title,due_date:title==='Validar y entregar'?deal.delivery_date||'':'',done:false,archived:false},0));
 return mergeOperations(list);
}
function assertTaskAllowed(task){const company=get('companies',task.company_id),deal=get('deals',task.deal_id);if(company&&companyStage(company,state.data)==='perdida'&&isPending(task)&&task.kind!=='entrega'&&deal?.stage!=='ganada')throw new Error('Esta empresa está en Perdido. Reabre su seguimiento antes de agendar otra acción comercial.');}
async function moveCompany(companyId,stage){
 const company=get('companies',companyId);if(!company)return;
 const current=companyStage(company,state.data);if(current===stage)return;
 const reopening=['ganada','perdida'].includes(current)&&!['ganada','perdida'].includes(stage);
 if(reopening&&!await confirmDialog('¿Reabrir el seguimiento de esta empresa?',`Se moverá a ${STAGES[stage]}. Se conservarán los cierres, cobros y entregas anteriores.`,'Reabrir seguimiento'))return;
 if(stage==='demo'){showForm(forms.contactLogForm(company,{move:true,allowReopen:reopening}));return;}
 if(stage==='perdida'){showForm(forms.lostCompanyForm(company));return;}
 if(stage==='ganada'){const deal=state.data.deals.find(row=>row.company_id===company.id&&isOpen(row));if(deal)showForm(forms.closeDealForm(deal,'ganada'));else showForm(forms.dealForm(state.data,{}, {stage:'ganada',company_id:company.id,title:`Proyecto para ${company.name}`.slice(0,220),need:company.need||'',closed_date:today()}));return;}
 await write(stageOperations(state.data,company,stage),`Empresa en ${STAGES[stage]}.`);initialForm='';formBack();
}
function assertVersion(type,recordId,version){const row=get(type,recordId);if((row?.version||0)!==Number(version))throw new ConflictError();return row;}
function importDialog(){importPlan=null;showDialog(`<div class="dialog-heading"><p class="eyebrow">TU META EMPIEZA CON UNA BUENA BASE</p><h2 id="dialog-title" tabindex="-1">Importar empresas.</h2><p>Revisa el archivo antes de guardar. Los duplicados no cuentan dos veces.</p></div><div class="import-start">${action('Descargar plantilla CSV','template',{icon:'download',class:'button secondary'})}<label class="file-drop">${icon('upload')}<strong>Elige tu archivo CSV</strong><span>Comas o punto y coma · Hasta 5 000 filas · Máximo 5 MB</span><input id="company-csv-file" type="file" accept=".csv,text/csv"></label><p class="form-help">Columnas mínimas: «empresa». La plantilla incluye categoría, ciudad, web, teléfono, fuente y contacto.</p></div><div id="import-review"></div>`,{kind:'import'},true);}
function reviewImport(){const plan=importPlan;if(!plan)return;const accepted=plan.accepted;$('#import-review').innerHTML=`<div class="import-summary"><div><strong>${accepted.length}</strong><span>Válidas para añadir</span></div><div><strong>${plan.duplicates.length}</strong><span>Duplicadas, se omiten</span></div><div><strong>${plan.errors.length}</strong><span>Con errores, se omiten</span></div></div><div class="import-preview"><h3>Vista previa · primeras ${Math.min(8,accepted.length)} válidas</h3><table><thead><tr><th scope="col">Fila</th><th scope="col">Empresa</th><th scope="col">Qué alquila</th><th scope="col">Ciudad</th></tr></thead><tbody>${accepted.slice(0,8).map(item=>`<tr><td>${item.line}</td><th scope="row">${e(item.company.name)}</th><td>${e(item.company.sector)}</td><td>${e(item.company.city)}</td></tr>`).join('')}</tbody></table></div>${plan.errors.length||plan.duplicates.length?`<details class="import-errors"><summary>Ver ${plan.errors.length+plan.duplicates.length} filas que no se guardarán</summary><ul>${[...plan.errors,...plan.duplicates].slice(0,80).map(item=>`<li><strong>Fila ${item.line} · ${e(item.name)}</strong> ${e(item.reason)}</li>`).join('')}</ul></details>`:''}<div id="import-status" role="status"></div><div class="form-footer">${action('Cancelar','cancel-form',{class:'button secondary'})}${action(`Importar ${accepted.length} empresas válidas`,'confirm-import',{class:'button',icon:'upload',extra:accepted.length?'':' disabled'})}</div>`;}
async function runImport(){if(!importPlan||state.importing)return;state.importing=true;let saved=0;const accepted=importPlan.accepted;const button=$('[data-action="confirm-import"]');button.disabled=true;try{for(let index=0;index<accepted.length;index+=8){const chunk=accepted.slice(index,index+8);const operations=[];for(const item of chunk){if(get('companies',item.company.id))continue;const duplicate=duplicateCompany(item.company,state.data.companies);if(duplicate)continue;operations.push(op('companies',item.company,0));if(item.contact)operations.push(op('contacts',item.contact,0));}if(operations.length)await write(operations,'');saved+=chunk.length;$('#import-status').textContent=`Guardadas ${saved} de ${accepted.length} empresas válidas…`;await new Promise(resolve=>setTimeout(resolve,0));}initialForm='';state.importing=false;closeDialog();navigate('empresas');toast(`Importación completada. Tu base tiene ${state.data.companies.length} empresas.`);}catch(error){state.importing=false;$('#import-status').textContent=`La importación se detuvo: ${friendly(error)} Las empresas ya confirmadas se conservan. Puedes continuar sin duplicarlas.`;button.disabled=false;button.textContent='Continuar importación';}finally{state.importing=false;render();}}
async function exportCompaniesExcel(){
 if(state.exportingCompanies)return;
 const data=structuredClone(state.data);state.exportingCompanies=true;render();
 try{const {createCompaniesExcel,EXCEL_MIME}=await import('./excel-export.js');const content=await createCompaniesExcel(data);download(`Nexo-empresas-${today()}.xlsx`,content,EXCEL_MIME);toast(`Excel descargado: ${data.companies.length} empresas con sus datos y contactos.`);}finally{state.exportingCompanies=false;render();}
}
function exportCompanies(){const rows=state.selectedCompanies.size?state.data.companies.filter(company=>state.selectedCompanies.has(company.id)):state.data.companies;download(`Nexo-empresas-${today()}.csv`,toCSV(rows,companyCSVFields),'text/csv;charset=utf-8');toast('CSV descargado.');}
function campaignValues(){const form=$('#campaign-form');return form?Object.fromEntries(new FormData(form)):{};}
function campaignCandidates(values){return filterCampaigns(state.data,values,state.selectedCompanies);}
function campaignPreview(){
 const form=$('#campaign-form'),target=$('#campaign-preview');if(!form||!target)return;const values=campaignValues(),rows=campaignCandidates(values);let sends=0,missing=0;const channels=values.channel==='ambos'?['correo','whatsapp']:[values.channel];for(const company of rows){const r=recipientFor(state.data,company);for(const ch of channels){if(ch==='correo'?r.email:r.choice?.phone)sends++;else missing++;}}
 const company=rows.find(c=>c.id===values.preview_company)||rows[0],template=company?sectorFor(company,values.template):'general';
 target.innerHTML=`<div class="campaign-audience"><div><strong>${rows.length}</strong><span>empresas que coinciden</span></div><div><strong>${sends}</strong><span>mensajes preparados</span></div><div><strong>${missing}</strong><span>sin dato para un canal</span></div></div><p class="form-help">Orden de la cola: ${rows.slice(0,5).map(c=>e(c.name)).join(' → ')}${rows.length>5?' → …':''}</p>${company?`${select('preview_company','Revisar el mensaje de',Object.fromEntries(rows.map(c=>[c.id,c.name])),company.id)}<div class="campaign-sample-head"><strong>Vista previa · ${e(company.name)}</strong><span>${e(SECTOR_LABELS[template])}</span></div><div class="campaign-samples">${channels.includes('correo')?`<section><h3>Correo</h3><p class="campaign-subject">${e(emailSubject(company.name,template))}</p><iframe title="Vista previa del correo" sandbox="" srcdoc="${e(emailHtml(company.name,template))}"></iframe><a class="text-link" href="${sectorAssets(template).pdf}" target="_blank" rel="noopener">Revisar el PDF de este rubro ${icon('diagonal')}</a></section>`:''}${channels.includes('whatsapp')?`<section><h3>WhatsApp con imagen</h3><img class="campaign-image" src="${sectorAssets(template).image}" alt="Presentación para ${e(SECTOR_LABELS[template])}" loading="lazy"><p class="campaign-caption">${e(sectorWhatsApp(company,template,{emailSent:values.channel==='ambos'&&!!recipientFor(state.data,company).email}))}</p></section>`:''}</div>`:'<p class="wa-notice">Ninguna empresa coincide. Ajusta los filtros antes de crear la campaña.</p>'}`;
 const submit=form.querySelector('[type=submit]');if(submit)submit.disabled=!sends||state.campaignBusy;
}
function campaignDialog(){
 const selected=state.selectedCompanies.size,valuesFor=key=>Object.fromEntries([...new Set(state.data.companies.map(c=>c[key]).filter(Boolean))].sort().map(v=>[v,v]));
 showDialog(`<div class="dialog-heading"><p class="eyebrow">CAMPAÑAS · COLA COMPARTIDA</p><h2 id="dialog-title" tabindex="-1">Preparar una campaña</h2><p>Elige a quién contactar y revisa el contenido. Puedes dejar varias campañas en cola.</p></div><form id="campaign-form" class="record-form"><div class="form-grid">${field('name','Nombre de la campaña',`Campaña ${dateLabel(today())}`,'required maxlength="120"')}${select('channel','Enviar por',{correo:'Correo desde Zoho',whatsapp:'WhatsApp con imagen',ambos:'Correo + WhatsApp'},'correo')}${select('template','Contenido por rubro',{auto:'Detectar según la categoría de cada empresa',impresion:SECTOR_LABELS.impresion,computadoras:SECTOR_LABELS.computadoras,general:SECTOR_LABELS.general},'auto')}${select('scope','Empresas a incluir',selected?{seleccionadas:`Solo las ${selected} seleccionadas`,todos:'Todas las que coincidan'}:{todos:'Todas las que coincidan'},selected?'seleccionadas':'todos')}${select('emailInterval','Intervalo entre correos',{60:'1 minuto · recomendado',120:'2 minutos',180:'3 minutos',300:'5 minutos'},'60')}${select('whatsappInterval','Intervalo entre WhatsApp',{30:'30 segundos · recomendado',60:'1 minuto',120:'2 minutos'},'30')}</div><details class="optional-fields campaign-filter-details" open><summary>Filtrar destinatarios</summary><div class="form-grid">${select('contacted','Contacto previo',{all:'Cualquier historial',never:'Nunca contactadas',contacted:'Ya contactadas'},'all')}${select('sent','Envíos anteriores',{all:'Sin filtro',never:'Sin correo ni WhatsApp',no_email:'Sin correo previo',no_whatsapp:'Sin WhatsApp previo',email:'Con correo previo',whatsapp:'Con WhatsApp previo',mixed:'Con ambos canales'},selected?'all':'never')}${select('stage','Etapa',{all:'Todas las etapas activas',diagnostico:'Filtrado',demo:'Contactado',propuesta:'Seguimiento',ganada:'Ganado'},'all')}${select('region','Zona',{all:'Lima y provincias',lima:'Solo Lima',provincias:'Fuera de Lima'},'all')}${select('city','Ciudad o provincia',{all:'Todas las ciudades / provincias',...valuesFor('city')},'all')}${select('district','Distrito',{all:'Todos los distritos',...valuesFor('district')},'all')}${select('sector','Categoría registrada',{all:'Todas las categorías',...valuesFor('sector')},'all')}${select('available','Datos disponibles',{all:'Sin filtro',correo:'Con correo',whatsapp:'Con WhatsApp',ambos:'Con ambos'},'all')}${select('last','Último envío',{all:'Cualquier fecha',over_7:'Sin envío en 7 días',over_30:'Sin envío en 30 días'},'all')}${select('order','Orden de las empresas',{oldest:'Más antiguas primero',newest:'Más recientes primero'},'oldest')}</div></details><div id="campaign-preview"></div><p class="form-help">Las empresas con un envío pendiente en el mismo canal se omiten. El intervalo es global por canal, incluso entre campañas distintas. El ritmo reduce ráfagas; no garantiza entrega en bandeja de entrada. Mantén una sesión del CRM abierta para procesar la cola. Al confirmarse cada envío, la empresa pasa de Filtrado a Contactado y se registran el canal, la fecha y la hora.</p><p class="form-error" role="alert" hidden></p><footer class="form-footer">${action('Volver','cancel-form',{class:'button secondary'})}<button class="button" type="submit">${icon('send')} Añadir a la cola</button></footer></form>`,{kind:'campaign'},true);campaignPreview();initialForm=currentFormSignature();
}
function campaignUpdateRequired(){return Object.assign(new Error('La campaña aún no se ha creado: falta actualizar el servidor de envíos de Supabase. Tus claves de Zoho y WhatsApp se conservan.'),{code:'OUTREACH_UPDATE_REQUIRED'});}
async function runCampaign(form){
 if(state.campaignBusy)return;if(!state.cloud||state.mode!=='cloud')throw new Error('Inicia sesión en el CRM para guardar campañas.');
 const values=Object.fromEntries(new FormData(form)),rows=campaignCandidates(values);if(!rows.length)throw new Error('No hay empresas que coincidan. Ajusta los filtros.');
 try{const capabilities=await state.cloud.email('capabilities');if(capabilities.templateVersion!==TEMPLATE_VERSION||capabilities.queue!==true)throw campaignUpdateRequired();}catch(error){if(error.code==='INVALID_REQUEST'||error.code==='FUNCTION_NOT_DEPLOYED')throw campaignUpdateRequired();throw error;}
 if(!await confirmDialog('¿Añadir esta campaña a la cola?',`${rows.length} empresas. ${values.channel==='ambos'?'Correo y WhatsApp':values.channel==='correo'?'Correo':'WhatsApp'}. Podrás preparar otra campaña mientras esta espera su turno.`,'Confirmar campaña'))return;
 state.campaignBusy=true;try{await state.cloud.email('campaign-create',{campaignId:id(),name:values.name,companyIds:rows.map(c=>c.id),channel:values.channel,template:values.template,emailInterval:Number(values.emailInterval),whatsappInterval:Number(values.whatsappInterval),filters:values});initialForm='';closeDialog();state.selectedCompanies.clear();await state.repo.load();navigate('envios');toast('Campaña guardada. Puedes preparar otra mientras se procesa.');queuePulse();}catch(error){if(error.code==='INVALID_REQUEST')throw campaignUpdateRequired();throw error;}finally{state.campaignBusy=false;}
}
let queueWorking=false,queueLastLoad=0;
async function queuePulse(){
 if(queueWorking||state.mode!=='cloud'||!state.ready||!state.connected)return;
 if(!queueNeedsWork(state.data))return;
 queueWorking=true;try{await state.cloud.email('campaign-tick');if(state.queueError){state.queueError='';if(state.route==='envios')render();}if(Date.now()-queueLastLoad>12000){queueLastLoad=Date.now();await state.repo?.load();}}catch(error){state.queueError=error.code==='INVALID_REQUEST'?'Actualiza las funciones privadas para activar la cola.':friendly(error);if(state.route==='envios')render();}finally{queueWorking=false;}
}
setInterval(queuePulse,5000);
async function campaignControl(button){const operation=button.dataset.type;if(operation==='cancel'&&!await confirmDialog('¿Cancelar los envíos pendientes?','Se conservan el historial y los envíos que el proveedor ya aceptó.','Cancelar pendientes'))return;await state.cloud.email('campaign-control',{id:button.dataset.id,operation});await state.repo.load();state.queueError='';toast(operation==='pause'?'Campaña pausada.':operation==='cancel'?'Pendientes cancelados.':'Campaña de nuevo en cola.');queuePulse();}
function campaignDetail(button){const campaign=state.data.settings.find(c=>c.id===button.dataset.id);if(!campaign)return;const counts=campaignCounts(campaign,state.data);showDialog(`<div class="dialog-heading"><p class="eyebrow">DETALLE DE CAMPAÑA</p><h2 id="dialog-title">${e(campaign.name)}</h2><p>${e(CAMPAIGN_LABELS[campaign.status])} · ${counts.sent} enviados · ${counts.errors} con error · ${counts.pending} pendientes</p></div><div class="campaign-detail-list">${counts.jobs.map(job=>`<article><div><strong>${e(get('companies',job.company_id)?.name||'Empresa')}</strong><small>${e(job.recipient)} · ${job.channel==='correo'?'Correo':'WhatsApp'} · ${e(SECTOR_LABELS[job.template])}</small></div><span class="badge ${job.status==='sent'?'green':''}">${e(DELIVERY_LABELS[job.status])}</span>${job.error?`<p>${e(job.error)}</p>`:''}</article>`).join('')}</div>`,{kind:'campaign-detail'},true);}

function exportDeals(){const fields=[{label:'oportunidad',value:'title'},{label:'empresa',value:deal=>get('companies',deal.company_id)?.name},{label:'etapa',value:deal=>STAGES[dealStageKey(deal)]},{label:'moneda',value:'currency'},{label:'importe',value:deal=>fromCents(deal.amount_cents)},{label:'cobrado',value:deal=>fromCents(paid(deal.id,state.data))},{label:'cierre_esperado',value:'expected_close'},{label:'cierre_real',value:'closed_date'},{label:'entrega',value:'delivery_date'},{label:'siguiente_paso',value:'next_step'},{label:'motivo_perdida',value:'lost_reason'}];download(`Nexo-oportunidades-${today()}.csv`,toCSV(state.data.deals,fields),'text/csv;charset=utf-8');}
function template(){const fields=[...companyCSVFields,{label:'contacto',value:'contact_name'},{label:'cargo',value:'contact_role'}];download('Nexo-plantilla-empresas.csv',toCSV([{name:'Empresa de alquiler de ejemplo',sector:'Maquinaria y construcción',city:'Lima',status:'nueva',priority:'media',website:'https://ejemplo.com',source_url:'https://ejemplo.com',contact_name:'Nombre del contacto',contact_role:'Administración'}],fields),'text/csv;charset=utf-8');toast('Plantilla descargada. Reemplaza la fila de ejemplo por tus empresas.');}
function searchDialog(){showDialog(`<div class="dialog-heading"><p class="eyebrow">TODO A MANO</p><h2 id="dialog-title">Buscar en tu CRM</h2></div><label class="search-field global-search-field">${icon('search')}<span class="sr-only">Buscar en todos los datos</span><input id="global-search" type="search" placeholder="Nombre, teléfono, correo, dirección o cualquier dato…" autocomplete="off"></label><div id="search-results"><p class="muted">Escribe para buscar en tus registros.</p></div>`,{kind:'search'});$('#global-search').focus();}
function searchResults(query){const needle=normalize(query);if(!needle){$('#search-results').innerHTML='<p class="muted">Escribe para buscar en tus registros.</p>';return;}const companies=state.data.companies.filter(row=>companyMatchesSearch(query,row,state.data)).slice(0,8);const deals=state.data.deals.filter(row=>matchesSearch(query,row,get('companies',row.company_id),state.data.contacts.filter(contact=>contact.company_id===row.company_id))).slice(0,8);const contacts=state.data.contacts.filter(row=>matchesSearch(query,row)).slice(0,8);$('#search-results').innerHTML=[['Empresas',companies,'open-company'],['Oportunidades',deals,'open-deal'],['Contactos',contacts,'open-contact-company']].map(([title,rows,name])=>rows.length?`<section><h3>${title}</h3>${rows.map(row=>action(`<span><strong>${e(row.name||row.title)}</strong><small>${e(row.sector||get('companies',row.company_id)?.name||'')}</small></span>${icon('diagonal')}`,name,{id:row.id,class:'search-result'})).join('')}</section>`:'').join('')||empty('No encontramos coincidencias.','Prueba con otro nombre.','','search');}
async function openConnection(){showDialog(connection(state.config),{kind:'connection'},true);}
async function logout(){goalsDraft=null;if($('#goals-form'))$('#goals-form').dataset.dirty='false';sessionStorage.removeItem('nexo-crm-demo-active');if(state.saving){toast('Espera a que el guardado termine antes de cerrar sesión.','error');return;}state.repo?.stop();state.repo=null;state.mode=null;state.ready=false;state.connected=false;state.data=emptyData();closeDialog();if(state.cloud)await state.cloud.logout();gateError='';render();}
function returnToDetail(type,recordId,tab=''){initialForm='';if(type==='companies')openCompany(recordId,tab||'resumen');if(type==='deals')openDeal(recordId,tab||'resumen');}

