 'confirm-restore':async()=>{
 if(!restorePlan||state.importing)return;state.importing=true;const order=['companies','contacts','deals','tasks','activities','milestones'];
 try{
  for(const type of order){const rows=restorePlan[type].filter(row=>!get(type,row.id));for(let i=0;i<rows.length;i+=8){await write(rows.slice(i,i+8).map(row=>{const copy={...row};delete copy.version;delete copy.created_at;delete copy.updated_at;if(type==='deals')copy.paid_cents=0;return op(type,copy,0)}),'');$('#restore-status').textContent=`Restaurando ${type}: ${Math.min(i+8,rows.length)} de ${rows.length}…`;}}
  const byDeal=Object.groupBy(restorePlan.payments.filter(row=>!get('payments',row.id)),row=>row.deal_id);
  for(const [dealId,payments] of Object.entries(byDeal)){for(let i=0;i<payments.length;i+=7){const deal=get('deals',dealId);const batch=payments.slice(i,i+7);const amount=batch.filter(row=>!row.voided).reduce((sum,row)=>sum+row.amount_cents,0);const operations=batch.map(row=>{const copy={...row};delete copy.version;delete copy.created_at;delete copy.updated_at;return op('payments',copy,0)});operations.push(op('deals',{...deal,paid_cents:(deal.paid_cents||0)+amount}));await write(operations,'');$('#restore-status').textContent='Restaurando cobros y verificando saldos…';}}
  state.importing=false;closeDialog();toast('Registros nuevos restaurados. Se conservaron los existentes.');
 }catch(error){$('#restore-status').textContent='Restauración detenida: '+friendly(error)+' Los registros confirmados se conservan.';toast(friendly(error),'error');}finally{state.importing=false;render();}
 },
 'reset-demo':async()=>{if(await confirmDialog('¿Restablecer los datos de prueba?','Solo se reiniciarán los ejemplos de este navegador.','Restablecer prueba'))await state.repo.reset();},
