 'copy-schema':async()=>{const response=await fetch('/SKYROTE13/instalar-crm.sql');if(!response.ok)throw new Error('No se pudo descargar el esquema.');const sql=await response.text();await navigator.clipboard.writeText(sql);toast('SQL copiado. Pégalo en SQL Editor y pulsa Run.');},
 'copy-rules':async()=>{const owner=$('#field-owner_uid').value.trim();if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(owner))throw new Error('Copia el UUID completo desde Authentication → Users.');const sql=`insert into public.crm_members(user_id) values ('${owner}'::uuid) on conflict do nothing;`;try{await navigator.clipboard.writeText(sql);$('#rules-feedback').textContent='Autorización copiada. Ejecútala en SQL Editor y luego inicia sesión.';}catch{download('Nexo-autorizar-usuario.sql',sql);$('#rules-feedback').textContent='Consulta descargada. Ejecútala en SQL Editor.';}},
